INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(1, 1, 1, '機械学習とは何ですか？', 'コンピュータがプログラムされたルールに従って動作する方法', 'コンピュータがデータから自動的にパターンを学習する方法', 'インターネット上のすべてのデータを分析する方法', 'AIが人間の指示なしに勝手に判断する能力', 1, '機械学習は、データからパターンを自動的に学習し、それを基に予測や判断を行う技術です。'),
(1, 1, 2, 'ディープラーニングはどのような技術ですか？', '複数の階層を持つニューラルネットワークを使った機械学習', 'インターネットの深い層にあるデータを学習する技術', '深い知識を必要とする機械学習', 'ビッグデータを処理するための技術', 0, 'ディープラーニングは、多層のニューラルネットワークを活用して、複雑なパターン認識を行う機械学習の一種です。'),
(1, 1, 3, 'クラウドコンピューティングの特徴として最も適切なものは何ですか？', 'インターネット経由で計算資源やストレージをオンデマンドで利用', '高性能なサーバーを社内に構築する方法', 'すべてのシステムをローカルコンピュータで実行', 'クラウドという名前のスーパーコンピュータ', 0, 'クラウドコンピューティングは、インターネット経由で計算やストレージなどのITリソースをオンデマンドで利用できるサービスです。'),
(1, 1, 4, 'AIの出現により企業が得られる主な利点は何ですか？', '全ての業務を完全に自動化できる', 'データ分析の自動化と業務効率の向上', 'コストをゼロにできる', 'セキュリティリスクを完全に排除できる', 1, 'AIは大量のデータを迅速に分析し、パターン認識や予測を行うことで、業務効率を向上させることができます。'),
(1, 1, 5, 'データとは何ですか？', '価値のある情報の集合体', 'インターネット上の全ての情報', 'コンピュータが扱う事実や観測結果', 'AI企業が所有する資産', 2, 'データは、事実や観測結果、測定値などの事柄を指し、情報処理の基本となる要素です。'),
(1, 1, 6, '機械学習を用いる場合、データの品質が重要な理由は何ですか？', 'データの量が多いほど精度が上がるため', 'データの品質が悪いと学習結果の精度が低下するため', 'データが多いほどセキュリティが高まるため', 'データ品質の基準はない', 1, '機械学習は入力データに基づいて学習するため、データに誤りやバイアスがあると、モデルの精度が低下します。'),
(1, 1, 7, 'クラウドのスケーラビリティとは何を意味しますか？', 'クラウドが世界中に広がっていること', 'システムの需要に応じて資源を柔軟に増減できること', 'クラウドの容量が無制限であること', 'クラウドが複数の企業で共有されること', 1, 'スケーラビリティは、需要の変化に応じてシステムのリソースを柔軟に拡張・縮小できる特性を指します。'),
(1, 1, 8, 'アルゴリズムとは何ですか？', 'インターネット検索に使う技術', 'コンピュータがプログラムに従うための処理手順や計算手法', 'データベースの一種', 'クラウドストレージを管理する方法', 1, 'アルゴリズムは、特定の問題を解決するための明確な手順や計算方法の集合です。'),
(1, 1, 9, 'なぜAIとクラウドを組み合わせるのですか？', 'クラウドはAIの学習に必要な大量の計算資源を提供するため', 'AIの方が速いから', 'セキュリティが向上するため', 'コストが安くなるため', 0, 'クラウドはスケーラブルな計算資源を提供し、AIの機械学習に必要な大規模なデータ処理を可能にします。'),
(1, 1, 10, '企業がAI・クラウドを導入する際の最初のステップは何ですか？', 'すぐに全業務をAI化する', 'ビジネスニーズと目標を明確にする', 'できるだけ多くのデータを集める', '最新のAI技術を全て導入する', 1, 'AI・クラウド導入の成功には、まずビジネスの課題や目標を明確にし、それに基づいて計画を立てることが重要です。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(1, 2, 1, 'IaaS、PaaS、SaaSの中で、ユーザーがアプリケーションを開発できるサービスはどれですか？', 'IaaS（Infrastructure as a Service）', 'PaaS（Platform as a Service）', 'SaaS（Software as a Service）', 'どれもアプリケーション開発には使えない', 1, 'PaaSは開発プラットフォームを提供し、ユーザーがその上でアプリケーションを開発・実行できます。'),
(1, 2, 2, 'SaaS（Software as a Service）の特徴として最も適切なものは何ですか？', 'ユーザーがOSやインフラを管理する必要がある', 'インターネット経由でアプリケーションを利用し、ベンダーが全て管理', 'プログラミング言語をユーザーが選べる', 'オンプレミス環境でのみ利用可能', 1, 'SaaSはベンダーがアプリケーション全体を管理し、ユーザーはブラウザやクライアント経由で利用するサービス形態です。'),
(1, 2, 3, 'AI APIとは何ですか？', 'AIが使うための基本的なプログラミング言語', 'AIの機能を利用するためのインターフェース', 'Amazonが提供するクラウドサービス', 'データセンターの一種', 1, 'AI APIは、提供者のAI機能を外部のアプリケーションから簡単に利用できるようにしたインターフェースです。'),
(1, 2, 4, 'クラウドサービスモデルの選択において、最もカスタマイズの自由度が高いのはどれですか？', 'SaaS', 'PaaS', 'IaaS', 'どれも同じ', 2, 'IaaSはインフラストラクチャを提供するため、OSやミドルウェアの選択やカスタマイズの自由度が最も高いです。'),
(1, 2, 5, 'データ分類とは何を指しますか？', 'データを時系列順に並べること', 'データの機密度や重要性に基づいて分類・管理すること', 'データを圧縮する方法', 'データベースのテーブル構造の決定', 1, 'データ分類は、データの機密性や重要度に基づいて分類し、適切な保護や管理方法を適用する重要なプロセスです。'),
(1, 2, 6, 'クラウドサービスを選択する際に考慮すべき重要な要素は何ですか？', 'ブランド名の知名度', 'コスト、セキュリティ、スケーラビリティ、サポート', '最も新しいサービス', 'ユーザー数が最も多いサービス', 1, 'クラウドサービス選択では、コスト効率、セキュリティ対策、スケーラビリティ、ベンダーサポートの質を総合的に評価する必要があります。'),
(1, 2, 7, 'AI APIを利用する際のセキュリティ上の注意点として最も重要なものは何ですか？', 'APIの利用費を安くすること', 'APIキーの安全な管理と通信の暗号化', 'APIを使用する時間を制限すること', 'できるだけ多くのデータを送信すること', 1, 'APIキーは認証情報であり、漏露するとアカウントが悪用される可能性があるため、安全に管理することが必須です。'),
(1, 2, 8, 'パブリッククラウド、プライベートクラウド、ハイブリッドクラウドの中で、最もセキュリティを厳格に管理できるものはどれですか？', 'パブリッククラウド', 'プライベートクラウド', 'ハイブリッドクラウド', 'どれも同じ', 1, 'プライベートクラウドは組織専用の環境であり、セキュリティポリシーを厳格に管理できます。'),
(1, 2, 9, 'データの「可用性」とは何を意味しますか？', 'データが誰にでもアクセスできること', '必要な時にデータにアクセスでき、利用できる状態であること', 'データが保存されている容量', 'データの更新頻度', 1, '可用性は、認可されたユーザーが必要な時にシステムやデータにアクセスできる状態を指します。'),
(1, 2, 10, 'マルチテナント環境におけるデータ分離が重要な理由は何ですか？', 'コストを削減するため', '複数のテナント間のデータが混在しないようにするため', '処理速度を向上させるため', 'データベースのサイズを削減するため', 1, 'マルチテナント環境では複数の顧客が同じシステムを使用するため、データの厳格な分離が顧客のプライバシー保護に必須です。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(1, 3, 1, 'AIモデルの種類として最も適切な分類は何ですか？', '教師あり学習、教師なし学習、強化学習', 'IaaS、PaaS、SaaS', 'パブリック、プライベート、ハイブリッド', 'GPU、CPU、メモリ', 0, 'AIモデルは学習データの提供方法によって、教師あり学習（ラベル付きデータで学習）、教師なし学習（ラベルなしデータで学習）、強化学習（報酬信号で学習）に分類されます。'),
(1, 3, 2, 'ディープラーニングモデルの選択において、画像認識タスクに最適なアーキテクチャはどれですか？', 'RNN（リカレントニューラルネットワーク）', 'CNN（畳み込みニューラルネットワーク）', 'LSTM', 'ランダムフォレスト', 1, 'CNN（畳み込みニューラルネットワーク）は画像の特徴抽出に最適化されており、画像認識タスクで高い精度を発揮します。'),
(1, 3, 3, 'クラウドアーキテクチャの設計において「冗長性」が重要な理由は何ですか？', '処理速度を向上させるため', 'コストを削減するため', 'システム障害時のサービス継続性を確保するため', 'データの暗号化を強化するため', 2, '冗長性により、障害が発生しても別の系統で処理を継続できるため、高可用性を実現できます。'),
(1, 3, 4, 'クラウドコストの最適化における「ライトサイジング」とは何ですか？', 'サーバーを軽くすること', 'インスタンスタイプを調整して実際の需要に合わせること', 'データを削減すること', 'クラウドの利用を中止すること', 1, 'ライトサイジングは、ワークロードに最適なサイズのインスタンスを選択することで、無駄なコストを削減する最適化手法です。'),
(1, 3, 5, 'トランスファーラーニング（転移学習）とは何ですか？', 'データをクラウド間で転送する', '既学習モデルの知識を新しいタスクに応用する学習手法', '学習データを異なるサーバーに転送する', 'AI企業の技術を他社に転送する', 1, '転移学習は、あるタスクで学習済みのモデルを別のタスクに活用することで、学習時間とデータ量を削減できます。'),
(1, 3, 6, 'クラウドアーキテクチャでマイクロサービスを採用する利点は何ですか？', 'システムが単純になること', 'サービスが独立してスケーリング・更新できる柔軟性', 'セキュリティが自動的に強化されること', 'データベースの管理が簡単になること', 1, 'マイクロサービスアーキテクチャは各機能を独立したサービスとして設計し、個別のスケーリングや更新が可能になります。'),
(1, 3, 7, 'ハイパーパラメータチューニングの目的は何ですか？', 'AIモデルのメモリ使用量を削減する', 'モデルのパフォーマンスを最適化するためのパラメータ値を決定する', 'クラウドの使用料を削減する', 'データセットのサイズを増やす', 1, 'ハイパーパラメータチューニングは、学習率や層数などのモデルパラメータを調整して、最適な性能を実現します。'),
(1, 3, 8, 'クラウドのオートスケーリング機能の役割は何ですか？', 'データを自動的にバックアップする', '負荷に応じてインスタンス数を自動的に調整する', 'セキュリティアラートを自動生成する', 'クラウド費用を自動的に支払う', 1, 'オートスケーリングは、トラフィック増加時にリソースを追加し、低下時に削減することで、パフォーマンスとコスト効率を両立させます。'),
(1, 3, 9, '教師なし学習の一般的な応用例として最も適切なものは何ですか？', '顔認識システム', 'メールのスパム分類', 'カスタマーセグメンテーション（顧客グループ分析）', '医療診断', 2, '教師なし学習はラベルなしデータからパターンを発見するため、カスタマーセグメンテーションなどのクラスタリングに適用できます。'),
(1, 3, 10, 'API Gatewayをクラウドアーキテクチャに導入する主な目的は何ですか？', 'データベースの容量を増やす', 'APIへのリクエストを一元管理し、認証・レート制限・ルーティングを行う', 'ユーザーインターフェースを改善する', 'AIモデルの精度を向上させる', 1, 'API Gatewayは、複数のバックエンドAPIへのリクエストを中央で管理し、セキュリティと負荷分散を実現します。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(2, 1, 1, '生成AIの安全な使い方として最も重要なものは何ですか？', '社外秘情報や個人情報を入力しない', 'できるだけ多くのデータを入力する', '暗号化なしで使用する', '個人のSNS投稿を学習データにする', 0, '生成AIは入力したデータを学習に使用する可能性があるため、社外秘情報や個人情報を入力してはいけません。'),
(2, 1, 2, 'プロンプトインジェクション攻撃とは何ですか？', 'AIモデルを物理的に破壊する攻撃', 'ユーザーが入力したデータに悪意のある命令を混ぜてAIを不正に操作する', 'クラウドのネットワークを遮断する攻撃', 'AI企業に不正侵入する攻撃', 1, 'プロンプトインジェクションは、入力内容に隠れた命令を埋め込み、AIに意図しない動作をさせる攻撃手法です。'),
(2, 1, 3, '企業がAI利用ルール（AI使用ポリシー）を定める主な理由は何ですか？', 'AIを全く使わせないため', 'セキュリティリスクを軽減し、適切なAI利用を推進するため', 'AIの開発者を雇用するため', 'クラウドのコストを削減するため', 1, 'AI利用ポリシーは、セキュリティリスクや情報漏洩を防ぎながら、適切にAIを活用するためのガイドラインです。'),
(2, 1, 4, '社員が生成AIを業務に使用する際、最初に確認すべきことは何ですか？', '自分の興味で選んだAIツール', '企業のAI利用ポリシーと許可されたツール', 'クラウドの無料トライアル版', '他社で使われているAIツール', 1, '企業のAI利用ポリシーに基づいて承認されたツールを使用することで、セキュリティと法令遵守を確保します。'),
(2, 1, 5, 'クラウドサービスのアカウント認証における基本的なベストプラクティスは何ですか？', '同じパスワードを複数のサービスで使う', '強力で一意のパスワード、多要素認証（MFA）の使用', 'パスワードを管理ツールに保存しない', 'パスワードをスタッフと共有する', 1, '強力でユニークなパスワードと多要素認証は、アカウントへの不正アクセスを防ぐ基本的なセキュリティ対策です。'),
(2, 1, 6, 'シャドーITとは何ですか？', 'IT部門が推奨する正式なシステム', 'IT部門の許可を得ずに使用されるクラウドツールやAIサービス', 'セキュアなクラウドストレージ', 'IT部門が管理するデータセンター', 1, 'シャドーITは、IT部門の管理外で従業員が勝手に導入・使用するツールであり、セキュリティリスクとなります。'),
(2, 1, 7, 'プロンプトインジェクション対策の基本的な方法は何ですか？', 'AIツールをまったく使わない', 'ユーザー入力を検証し、信頼できるデータのみを使用する', 'インターネット接続を遮断する', '全てのデータを暗号化する', 1, 'プロンプトインジェクション対策として、ユーザー入力の妥当性を検証し、予期しないコマンドが混在しないようにする必要があります。'),
(2, 1, 8, 'AI利用時に企業の機密情報を漏洩させないためには何が重要ですか？', 'クラウドを使わない', 'どのような情報が機密か理解し、外部AIに入力しないこと', '全員に同じパスワードを配布する', '暗号化せずに全てのデータを公開する', 1, '社員が企業の機密度を理解し、社外秘情報を外部のAIサービスに送信しないことが重要です。'),
(2, 1, 9, 'クラウドサービスの利用契約書を確認する際に注目すべきポイントは何ですか？', 'サービスの価格だけ', 'データの所有権、プライバシーポリシー、サービスレベル合意（SLA）', 'デザインの見た目', 'サービス企業の企業規模', 1, '利用契約書でデータ所有権、プライバシー保護、サービス可用性などの重要事項を確認することが必須です。'),
(2, 1, 10, '社内でAIツールを導入する際の推奨事項は何ですか？', 'いくつかのツールを密かに試す', 'IT部門と協力して評価・承認し、ポリシーに基づいて導入する', 'コストが最安値のツールを選ぶ', '全社員に説明なしで強制導入する', 1, 'IT部門の支援を受けて適切に評価・承認されたツールの導入により、セキュリティと運用効率を確保できます。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(2, 2, 1, 'ロールベースアクセス制御（RBAC）の利点は何ですか？', 'ユーザー全員に同じ権限を付与', 'ユーザーの役割に応じた適切なリソースアクセスを自動管理', 'セキュリティ対策は不要', 'パスワードを共有することで利便性が向上', 1, 'RBACは各ユーザーの職務に必要なアクセス権限のみを付与し、最小権限の原則を実現します。'),
(2, 2, 2, 'データ分類ラベル（Confidential、Internal、Public等）の目的は何ですか？', 'ファイルを色分けして見やすくする', 'データの機密度に応じた保護レベルを決定する', 'ファイルサイズを縮小する', 'データの作成日時を記録する', 1, 'データ分類ラベルにより、各データに適切な保護・アクセス制限・保持期間などのポリシーを適用できます。'),
(2, 2, 3, 'APIキーの安全な管理方法として最も推奨されるものは何ですか？', 'ソースコード内に埋め込む', '環境変数やシークレット管理サービスで管理', 'テキストファイルに保存する', '全員に共有する', 1, 'APIキーは環境変数やセキュアなシークレット管理サービスで保管し、ソースコードには埋め込まないことが必須です。'),
(2, 2, 4, 'クラウドストレージにおけるアクセス権限管理の重要性は何ですか？', 'ユーザーの満足度を高めるため', 'データへのアクセスを許可された者だけに制限し、情報漏洩を防ぐため', 'ストレージの容量を増やすため', 'ファイルの読み込み速度を向上させるため', 1, '適切なアクセス権限管理により、不正なアクセスやデータ流出を防ぎ、機密情報を保護できます。'),
(2, 2, 5, 'データ暗号化における「転送中の暗号化」と「保存時の暗号化」の違いは何ですか？', 'どちらも同じである', 'データ転送時と保存時の両方で異なる暗号化方式を適用する', 'どちらか一方だけで十分', 'どちらも不要', 1, '転送中と保存時で異なる暗号化を行うことで、データの全ライフサイクルにおいてセキュリティを確保します。'),
(2, 2, 6, 'AIクラウドサービスにおける「監査ログ」の役割は何ですか？', 'システムの動作速度を記録する', 'ユーザーの操作や重要なシステムイベントを記録し、セキュリティ分析や法令遵守に活用', 'ユーザーの趣味嗜好を記録する', 'サービスの利用料金を記録する', 1, '監査ログはアクティビティを記録し、セキュリティインシデント調査や法的要件への対応に不可欠です。'),
(2, 2, 7, 'シャドーITのリスク軽減策として最も有効なものは何ですか？', 'セキュリティを完全に無視する', 'IT部門が許可・管理するツールを推奨し、シャドーITの利用を検出・報告する仕組みを構築', 'すべてのインターネット接続をブロック', 'ユーザーに何も指示しない', 1, 'シャドーIT検出と管理を通じて、セキュリティリスクを最小化しながら業務効率を維持できます。'),
(2, 2, 8, 'エンドツーエンド暗号化（E2EE）の特徴は何ですか？', '暗号化が不要である', 'サービスプロバイダーを含む第三者がデータを復号化できない', '転送速度が極端に低下する', '暗号化鍵を誰もが共有する', 1, 'E2EEではデータはユーザーの端末で暗号化され、サービスプロバイダーであってもデータの内容を見ることはできません。'),
(2, 2, 9, 'マルチクラウド戦略を採用する際の主な利点は何ですか？', 'ベンダーロックイン回避とサービス可用性の向上', 'すべてのサービスが統一される', 'セキュリティが不要になる', 'コストが確実に削減される', 0, 'マルチクラウド導入により、特定ベンダーへの依存を減らし、冗長性とサービス継続性を実現できます。'),
(2, 2, 10, 'クラウドデータのバックアップ戦略で重視すべき要素は何ですか？', 'バックアップの頻度のみ', '頻度、保存場所の分散、復旧時間目標（RTO）、復旧地点目標（RPO）', 'バックアップコストだけ', 'バックアップは不要', 1, '適切なバックアップ戦略では、複数の要素を考慮してデータ損失時の迅速な復旧を実現します。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(2, 3, 1, 'マルチクラウドアーキテクチャにおけるデータ同期の課題と対策は何ですか？', '複数クラウド間のデータ一貫性を保ちながら、リアルタイム同期とコンフリクト解決が必要', 'データ同期は不要', 'すべてのデータを1つのクラウドに集約すればよい', 'データベースの構造を定期的に変更する', 0, 'マルチクラウド環境でのデータ同期には、整合性を保つための仕組みと、障害発生時のコンフリクト解決が重要です。'),
(2, 3, 2, 'APIゲートウェイを使用してマルチクラウドAI機能を管理する利点は何ですか？', 'すべてのAPIを1箇所で管理・制御し、セキュリティとレート制限を統一的に実装', 'APIの数を減らす', 'セキュリティを廃止する', 'ユーザーインターフェースを改善する', 0, 'APIゲートウェイは複数のバックエンドサービスへのアクセスを一元管理し、認証・監視・トラフィック制限を実現します。'),
(2, 3, 3, 'データレイク構築における主な課題は何ですか？', 'すべてのデータを保存するだけで十分', 'データ品質の保証、メタデータ管理、ガバナンス、不正アクセス防止', 'データの量より質は重要でない', 'バックアップは不要', 1, 'データレイクを効果的に運用するには、データカタログ、品質管理、アクセス制御などの総合的なガバナンスが必須です。'),
(2, 3, 4, 'クラウドネイティブアプリケーションのセキュリティにおいて重要な要素は何ですか？', 'パスワード認証のみで十分', 'コンテナセキュリティ、マイクロサービス間通信の暗号化、ランタイム保護', 'セキュリティは開発完了後に追加する', 'すべてのユーザーに管理者権限を付与', 1, 'クラウドネイティブ環境では、コンテナレベルのセキュリティ、ネットワークセキュリティ、ランタイム監視が重要です。'),
(2, 3, 5, '分散トレーシングの目的は何ですか？', 'ユーザーの位置情報を追跡する', 'マイクロサービス間のリクエスト流れを可視化し、パフォーマンス問題やエラーを特定', 'インターネット速度を測定する', 'データを秘密裏に監視する', 1, '分散トレーシングはマイクロサービスアーキテクチャにおいて、複雑なリクエスト経路を可視化し、問題箇所を特定します。'),
(2, 3, 6, 'サービスメッシュ（Service Mesh）を導入する理由は何ですか？', 'マイクロサービス間通信の管理、セキュリティ、観測可能性（observability）を向上', 'すべてのシステムをシンプルにする', 'デバッグを不要にする', 'コストを削減するのみ', 0, 'サービスメッシュは、マイクロサービス間の通信ポリシー適用、トラフィック制御、セキュリティを統一的に管理します。'),
(2, 3, 7, 'API仕様（OpenAPI/Swagger）の重要性は何ですか？', 'APIの見た目を改善するため', 'API機能、パラメータ、レスポンスを標準化し、開発効率とセキュリティを向上', 'APIの呼び出し速度を上げるため', '開発者教育の代わりになる', 1, 'API仕様の標準化により、API開発の効率化、ドキュメント自動生成、セキュリティ検証が実現します。'),
(2, 3, 8, 'データレイクセキュリティにおける最小権限の原則の適用例は何ですか？', 'すべてのユーザーに全データへのアクセスを許可', 'ユーザーが必要最小限のデータセットにのみアクセス可能とする', 'セキュリティは無視する', 'アクセス制御を定期的に廃止する', 1, '最小権限の原則により、ユーザーは担当業務に必要なデータのみにアクセスでき、不正アクセスのリスクを低減できます。'),
(2, 3, 9, 'API開発におけるレート制限（Rate Limiting）の役割は何ですか？', 'APサービスの応答を遅くする', 'DoS攻撃を防ぎ、フェアな利用配分とAPI品質を維持', 'ユーザーを増やすため', 'ログ記録を削減する', 1, 'レート制限は悪意のあるアクセスや過度な利用から API を保護し、公平で安定したサービス提供を実現します。'),
(2, 3, 10, 'キーローテーション（APIキーの定期更新）がなぜ重要なのか説明してください。', 'キーの有効期限を忘れないため', '長期使用されたキーが漏洩した場合のリスク期間を限定し、セキュリティを向上', 'ユーザーに手間をかけさせるため', 'キーのサイズを小さくするため', 1, 'キーローテーションにより、万が一キーが漏洩しても被害期間を最小化でき、セキュリティの侵害を防ぐことができます。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(3, 1, 1, 'ディープフェイクとは何ですか？', '深い知識が必要な情報', 'AIを使用して実在しない映像や音声を生成する技術', '詳細な情報のこと', 'インターネットの深い部分', 1, 'ディープフェイクはディープラーニングを使用して、実際には起きていないシーン（虚偽映像や音声）を生成する技術です。'),
(3, 1, 2, 'ディープフェイクの社会的リスクとして最も懸念されるものは何ですか？', 'インターネット速度の低下', '詐欺、評判毀損、政治的操作、なりすまし犯罪', 'ファイルサイズの増加', 'キーボード入力の遅延', 1, 'ディープフェイクは偽の映像・音声を本物そっくりに生成でき、詐欺やデマ、個人への危害に悪用される危険があります。'),
(3, 1, 3, '自動フィッシング攻撃（AI-powered Phishing）とは何ですか？', 'インターネット上の魚に関する情報', 'AIが個人向けにカスタマイズされた詐欺メールを大規模に生成・送信する攻撃', 'フィッシング産業の統計', 'ネットワークの接続速度低下', 1, 'AI自動フィッシングは、機械学習を使用して個人に応じた説得力のあるメールを自動生成し、不正アクセスを試みます。'),
(3, 1, 4, 'AIを悪用した攻撃から防御する基本的な方法は何ですか？', '全てのAIツールを禁止する', '怪しいメール・リンク・ファイルを慎重に扱い、多要素認証を使用する', 'インターネット接続を遮断する', 'すべてのデータを公開する', 1, 'AIを使った攻撃への防御は、ユーザー教育、強力な認証、異常検知システムの組み合わせが有効です。'),
(3, 1, 5, 'なぜディープフェイクの検出が難しいのですか？', '技術が単純すぎるため', 'AI生成技術の精度が高く、人間の目では判別が困難な場合がある', '検出ツールが不足しているため', 'インターネット接続が遅いため', 1, 'ディープラーニング技術の進歩により、ディープフェイクの精度が向上し、肉眼での判別がほぼ不可能になっています。'),
(3, 1, 6, '個人がフィッシング攻撃から身を守るために何をすべきですか？', 'メールを全く開かない', 'メールの送信者を確認し、不審なリンク・添付ファイルをクリックしない', 'パスワードを簡単にする', 'パスワードを誰かに教える', 1, 'フィッシング詐欺への対策として、送信者検証、不審なリンク・添付ファイルの回避が重要です。'),
(3, 1, 7, 'なりすまし詐欺における高度なAI活用の例は何ですか？', 'メール送信者の名前を変更するだけ', 'AI が実際の取引相手の声や動画を合成し、送金指示など詐欺行為を行う', '迷惑メールの自動削除', 'セキュリティソフトの更新', 1, 'AI技術により、実際の人物になりすまして、金銭詐欺や機密情報の窃取などが可能になっています。'),
(3, 1, 8, 'ボット攻撃（Bot Attack）とは何ですか？', 'ロボットを操作する方法', '自動化されたマルウェアが大量にサーバーを攻撃するサイバー攻撃', 'インターネットサービスプロバイダー', 'Botaと呼ばれるツール', 1, 'ボット攻撃は自動化されたマルウェアがDDoS攻撃やデータ窃取などを大規模に実行します。'),
(3, 1, 9, 'AIを使用した脅威検知システムの利点は何ですか？', '完全に攻撃を防ぐことができる', 'リアルタイムで異常パターンを検出し、既知・未知の脅威を素早く特定', 'すべての脅威が判明する', 'セキュリティが不要になる', 1, 'AI-ベースの異常検知は、従来のルールベース検知では検出できない新しい脅威パターンを発見できます。'),
(3, 1, 10, 'サイバー脅威がAI技術により深刻化する理由は何ですか？', 'AIが面倒になるため', 'AIにより攻撃の規模、精度、自動化度が飛躍的に向上するため', 'AI企業が多くなったため', 'インターネットが遅くなるため', 1, 'AI技術は攻撃の規模化・自動化・カスタマイズを可能にし、防御を一層困難にしています。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(3, 2, 1, '敵対的攻撃（Adversarial Attack）とは何ですか？', 'AIモデルを直接壊す攻撃', 'AIモデルを騙すために入力データを意図的に変更する攻撃', '物理的にコンピュータを破壊する行為', 'ソフトウェアのバグを利用する方法', 1, '敵対的攻撃は、AIモデルの入力に微妙な修正を加えることで、モデルを誤判定させる攻撃です。'),
(3, 2, 2, 'データポイズニング（Data Poisoning）の危険性は何ですか？', 'データの量が減ること', '悪意者が学習データを改ざんしてモデルを意図的に誤作動させること', 'データベースのサイズが大きくなること', 'データの保存場所が分散されること', 1, 'データポイズニングは学習段階でデータを汚染し、完成したモデルに不具合や意図しない動作を埋め込む高度な攻撃です。'),
(3, 2, 3, 'モデル窃取（Model Extraction）とは何ですか？', 'AIモデルを物理的に盗む行為', 'APIクエリなどを通じて、機密のAIモデルの構造や重みを抽出する', 'モデルのドキュメントをコピーする', 'グラフィックスモデルを変更する', 1, 'モデル窃取は、入出力を繰り返し試して、機密モデルと同等の代理モデルを再現する攻撃です。'),
(3, 2, 4, 'メンバーシップ推論攻撃（Membership Inference Attack）とは何ですか？', 'チームメンバーを推測する', 'AIモデルへの問い合わせを通じて、特定のデータが学習に使用されたか判定する攻撃', 'ユーザー認証を突破する', 'ネットワークの構成を調べる', 1, 'メンバーシップ推論攻撃は、モデルの挙動を分析して、個人データが学習に含まれていたかを判定し、プライバシーを侵害します。'),
(3, 2, 5, 'AI モデルのバックドア攻撃とは何ですか？', 'モデルの背後にあるサーバーへの攻撃', '攻撃者が開発段階でモデルに隠れた機能を埋め込み、後に悪用する', 'モデルの重みファイルを削除する', 'モデルの出力を改ざんする', 1, 'バックドア攻撃は、開発段階でトリガー条件を検出して特定の不正動作を実行するように仕込まれた脆弱性です。'),
(3, 2, 6, '敵対的攻撃への防御方法として最も有効なものは何ですか？', '全てのAIを使わない', 'ロバストなモデル開発、入力検証、異常検知システムの導入', 'AIを一時的に停止する', 'セキュリティソフトのインストール', 1, '敵対的攻撃への防御には、ロバストなAIモデルの開発、入力データの検証、異常検知が組み合わされます。'),
(3, 2, 7, 'トランスファーラーニングが持つセキュリティリスクは何ですか？', 'ネットワーク速度の低下', '事前学習モデルにバックドアが仕込まれていると、転移学習を通じてそれが新モデルに引き継がれる可能性', 'ファイルサイズが大きくなること', 'ディスク容量の不足', 1, '転移学習時に事前学習モデル自体が悪意で改ざんされていると、新しいタスクでもその脆弱性が継承されます。'),
(3, 2, 8, 'AI の「バイアス」がセキュリティに与える影響は何ですか？', 'セキュリティに影響しない', 'バイアスのあるAIは特定の層の攻撃に弱いなど、セキュリティの脆弱性につながる可能性', 'バイアスはAIを強くする', '全てのバイアスは検出可能である', 1, 'AIのバイアス（偏り）は特定のシナリオで誤判定を引き起こし、セキュリティシステムの盲点を作ります。'),
(3, 2, 9, 'API 経由のモデル窃取攻撃を防ぐ方法は何ですか？', 'APIを誰でも使えるようにする', 'APIへのアクセスを制限し、異常なクエリパターンを監視・検出', 'APIを複雑にする', 'クエリ数に制限を設けない', 1, 'モデル窃取防止には、アクセス制限、レート制限、クエリパターン監視が必要です。'),
(3, 2, 10, 'プライバシー保護とAIセキュリティの関係性は何ですか？', '無関係である', 'メンバーシップ推論やモデル反転攻撃から個人情報を守るため、プライバシー技術がAIセキュリティに統合されている', '個人情報はセキュリティと無関係', 'プライバシーはAIでは不要', 1, 'AI時代のプライバシー保護には、差分プライバシー、フェデレーション学習など、プライバシー保護型AI技術が不可欠です。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(3, 3, 1, 'AIサプライチェーン攻撃における最大の脅威は何ですか？', '配送遅延', 'データセット、事前学習モデル、学習環境が侵害され、複数のAIシステムが影響を受ける', 'AIの性能低下', 'クラウドサービスの価格上昇', 1, 'AIサプライチェーン攻撃では、一度のコンポーネント侵害が多数のダウンストリームシステムに波及します。'),
(3, 3, 2, 'OWASP Top 10 for LLMs（大規模言語モデルの10大脅威）の主な脅威は何ですか？', 'LLMはセキュアである', 'プロンプトインジェクション、訓練データの漏洩、モデル出力の暴露など', 'LLMには脅威がない', 'セキュリティは不要', 1, 'OWASP Top 10 for LLMsはLLM固有の脅威を整理し、プロンプトインジェクション、トレーニングデータ漏洩などを含みます。'),
(3, 3, 3, 'プロンプトインジェクション攻撃の高度な例は何ですか？', 'ユーザーが直接入力することのみ', 'システムプロンプトを上書きして、外部ユーザーが入力した文字列を通じてLLMの動作を乗っ取る', 'メールを送信する', 'ファイルを削除する', 1, '高度なプロンプトインジェクションでは、攻撃者はLLMのシステムプロンプトを上書きしてその動作を完全にコントロール可能です。'),
(3, 3, 4, 'エンドツーエンド（E2E）ベースのAIセキュリティ検証の重要性は何ですか？', 'セキュリティ検証は不要', '個別のコンポーネントだけでなく、全体の処理パイプラインを検査し、予期しない相互作用や脆弱性を検出', 'テストは実施しない', 'すべてのコンポーネントは安全である', 1, 'E2Eセキュリティテストはシステム全体の統合的なセキュリティを検証し、個別テストでは見つからない脆弱性を発見します。'),
(3, 3, 5, 'ゼロデイ脆弱性とAIセキュリティの関係は何ですか？', '無関係である', 'AIの新しい脆弱性（未修正）が発見されると、攻撃者が即座に悪用し、組織に深刻な被害を与える可能性', 'AIは脆弱性がない', 'ゼロデイは古い脆弱性', 1, 'AI技術は急速に進化するため、既知の防御方法が新しい脆弱性には対応できないゼロデイリスクが高い。'),
(3, 3, 6, '差分プライバシー（Differential Privacy）がAIセキュリティに果たす役割は何ですか？', 'プライバシーはセキュリティと無関係', 'メンバーシップ推論など個人情報抽出攻撃に対する耐性を数学的に保証しながらAIを学習させる', 'プライバシーを無視する', 'セキュリティを弱くする', 1, '差分プライバシーはAIモデル学習時に数学的に個人情報の露出リスクを制限し、プライバシーを保護します。'),
(3, 3, 7, 'フェデレーション学習（Federated Learning）がセキュリティに与える利点は何ですか？', 'セキュリティは向上しない', 'デバイスローカルでモデル学習し、中央サーバーは集計値のみ受け取るため、個人データの集中化とその漏洩リスクが低減', 'すべてのデータを集約する', 'プライバシーを放棄する', 1, 'フェデレーション学習は個人データをデバイスに留めることで、大規模データ漏洩のリスクを根本的に低減できます。'),
(3, 3, 8, '敵対的学習（Adversarial Training）がAIロバストネスに与える効果は何ですか？', 'セキュリティを悪化させる', '意図的に敵対的な例を学習データに含め、不正な入力に対するモデルの耐性を向上させる', 'モデルの精度が低下する', '学習が不要になる', 1, '敵対的学習によって、モデルは攻撃者の意図しない入力に対しても堅牢に動作する能力を獲得します。'),
(3, 3, 9, 'AIモデルの検証（Validation）と検証（Verification）の違いは何ですか？', 'どちらも同じ', '検証はモデルが仕様通り動作するかの確認、検証はセキュリティなど非機能要件の確認を指す場合がある', '両方とも不要', '区別する必要がない', 1, 'AI開発では、機能検証だけでなく、セキュリティ脆弱性やバイアスなどの検証が同等に重要です。'),
(3, 3, 10, 'AIモデルの説明可能性（Explainability）がセキュリティに与える役割は何ですか？', '説明可能性は不要', 'モデルの判断根拠を可視化することで、異常な動作やバックドア、攻撃の痕跡を検出しやすくなる', '説明可能性はプライバシーを侵害する', 'セキュリティと無関係', 1, '説明可能なAIは攻撃者が仕込んだ隠れた振る舞い（バックドア）を検出するための重要なツールです。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(4, 1, 1, 'AI倫理とは何を指しますか？', 'AIの開発コストの削減', 'AIシステムが公正で透明性があり、人間の価値観や権利を尊重するよう設計・運用されるべき原則', 'AIの性能を最大化すること', 'AIを高速化すること', 1, 'AI倫理は、AIが社会に及ぼす影響を考慮し、公正性、透明性、説明可能性などの原則に基づいて開発・運用されるべきという考え方です。'),
(4, 1, 2, 'AIのアルゴリズムバイアスとは何ですか？', 'プログラムのバグ', 'AIモデルが特定の属性（性別、人種など）に対して差別的な判定を行うこと', 'ソフトウェアの単なる誤り', 'インターネットの遅延', 1, 'アルゴリズムバイアスは、学習データや設計の問題により、特定の層に対して不公正な判定をするAIの動作です。'),
(4, 1, 3, '個人情報保護法（GDPR など）が AI 開発に課す制限は何ですか？', 'AI開発は完全に禁止される', '個人データの適切な管理、本人同意の取得、データ削除権（忘れられる権利）の尊重', 'データを自由に集約できる', 'ユーザー同意は不要', 1, 'GDPRなどの法律は、個人データをAI学習に使用する際、透明性、同意、データ管理の厳格な基準を定めています。'),
(4, 1, 4, '生成AIの著作権問題における主な課題は何ですか？', '著作権は存在しない', 'AIが著作権で保護された作品を学習データとして無断使用することと、AI生成物の著作権帰属が不明確である点', '著作権は保護されない', 'すべての作品は自由に使える', 1, 'AI学習における著作権と、AI生成物の権利帰属は未解決の重要な法的課題です。'),
(4, 1, 5, 'AI利用における「責任の所在」の問題とは何ですか？', 'AIの責任は誰にもない', 'AI判定に誤りや差別があった場合、開発者か利用企業のどちらが責任を負うかが不明確である点', 'すべての責任はユーザーにある', '法的責任は存在しない', 1, 'AI時代では、判定エラーや害をもたらす出力が発生した時の法的・倫理的責任の所在を明確にすることが重要です。'),
(4, 1, 6, 'AIシステムの説明可能性が重要な理由は何ですか？', 'システムの見た目を改善するため', 'ユーザーが判定理由を理解でき、不公正な判定に異議を唱えるため', 'データを保存する手間を減らすため', 'セキュリティと無関係', 1, '説明可能性により、AIの判定が公正で透明であることを確認でき、信頼を構築できます。'),
(4, 1, 7, 'AIガバナンスフレームワークの主要要素は何ですか？', 'AI開発の完全な禁止', 'ポリシー策定、倫理審査、継続的な監視、利害関係者の参画', '開発者への制限がない', 'ルールの厳格化のみ', 1, 'AIガバナンスフレームワークは、倫理、法令遵守、リスク管理、透明性を統合的に管理する仕組みです。'),
(4, 1, 8, 'AIの「公正性（Fairness）」とは何を意味しますか？', 'AIのサービス料金が安いこと', 'すべての個人・グループに対して不当な差別をしないこと', 'AIのパフォーマンスが高いこと', 'AIの計算速度が速いこと', 1, '公正性は、AIが個人の不当な属性（人種、性別など）に基づいて判定を変えないことを意味します。'),
(4, 1, 9, 'AI倫理委員会の役割は何ですか？', 'AIの使用禁止を推し進める', 'AIプロジェクトの倫理的妥当性を審査し、リスクを評価・管理すること', 'AI開発速度を加速させる', '倫理は考慮しない', 1, 'AI倫理委員会は、倫理的懸念を事前に検証し、組織全体でAIの倫理的運用を確保します。'),
(4, 1, 10, 'AI開発における透明性（Transparency）の重要性は何ですか？', 'すべてを公開する必要がある', 'AIの仕組み、判定根拠、局限を利用者が理解できるようにすることで、信頼と説明責任を確保', '透明性は不要', 'セキュリティと矛盾する', 1, '透明性は、AIシステムがどのように判定しているかをユーザーが理解できることで、信頼と制御可能性を実現します。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(4, 2, 1, 'AIリスクマネジメントの5つの主要なステップは何ですか？', 'リスク特定と評価、対策実施、監視、報告、改善', 'すべてのAIは禁止する', 'リスク特定のみで十分', 'リスク対策は不要', 0, 'AIリスクマネジメントは、脅威を特定・評価し、対策を実施して継続的に監視・改善するサイクルです。'),
(4, 2, 2, 'EU AI Act の主な要件は何ですか？', 'AIの使用を全面禁止', 'リスクレベルに応じたAIの規制（高リスクAIには透明性・監視を義務付け）', 'AIは規制対象外', 'リスク評価は不要', 1, 'EU AI Actは、AIシステムをリスクレベルで分類し、高リスクAIに対して透明性、人間の監視、説明責任を要求しています。'),
(4, 2, 3, '「責任あるAI（Responsible AI）」の要素として最も重要なものは何ですか？', 'AI開発の推進のみ', '公正性、説明可能性、プライバシー保護、セキュリティ、人間中心の設計', 'コスト削減のみ', '規制への準拠は不要', 1, '責任あるAIは、倫理的な値と実践的なセキュリティ・プライバシーを統合した包括的なアプローチです。'),
(4, 2, 4, 'AIプロジェクトのインパクト評価（Impact Assessment）の目的は何ですか？', '開発計画を延長すること', 'AIが社会・利用者に与える潜在的な害を事前に特定し、対策を講じること', '開発費用を増やすこと', 'リスク評価は不要', 1, 'インパクト評価は、AIシステムが運用される際に発生しうる負の影響を予測し、軽減策を計画します。'),
(4, 2, 5, 'AIの意思決定の「監査可能性」とは何を指しますか？', 'AIが全く説明できない状態', 'AIの判定履歴が記録され、事後的に検証・監査可能な状態', 'AIは監視する必要がない', '監査は法的要件ではない', 1, '監査可能性により、AIが誤った判定を行った場合、その原因を事後的に調査・説明できます。'),
(4, 2, 6, 'データ同意（informed consent）における AI の課題は何ですか？', '同意は不要', 'ユーザーが AI学習用の個人データ利用に関する詳細な影響を完全に理解して同意するのが現実的に困難', 'ユーザーは常に理解している', '透明性は必要ない', 1, 'AI時代のデータ同意では、複雑な技術を平易に説明し、真の理解に基づいた同意を得る必要があります。'),
(4, 2, 7, 'AI監視機関（AI Oversight Board）の責務は何ですか？', 'AI開発を禁止すること', 'AIの倫理的・法的合規性を監視し、問題があれば是正措置を勧告', 'AIの自由な利用を促進するのみ', '監視は不要', 1, 'AI監視機関は、組織外の独立した視点でAIの倫理的・法的妥当性を継続的にチェックします。'),
(4, 2, 8, 'AIの「アカウンタビリティ（Accountability）」とは何を意味しますか？', 'AIは誰の責任でもない', 'AIの決定・動作について、その組織が説明・証明し、問題時に責任を負うこと', '責任者を決める必要がない', 'アカウンタビリティは法的要件ではない', 1, 'アカウンタビリティにより、AIの不適切な使用に対して、組織と責任者が法的・倫理的責任を問われます。'),
(4, 2, 9, 'AI開発における「by design」アプローチの意義は何ですか？', '開発後にセキュリティを追加する', 'セキュリティ・倫理・プライバシーを開発の初期段階から組み込む設計思想', '倫理は後付けでいい', 'セキュリティは実装時に追加する', 1, 'Security by Design/Ethics by Designにより、システムが本質的にセキュアで倫理的な運用を実現できます。'),
(4, 2, 10, '人間中心AI（Human-Centric AI）の設計原則は何ですか？', 'AIに完全に判定を委ねる', 'AIの最終判定に人間が関与し、責任ある意思決定を確保すること', '人間の関与は不要', 'AIは人間と独立すべき', 1, '人間中心AIでは、重大な判定については最終的に人間が決定・責任を負うことで、エラーや倫理的問題を軽減します。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(4, 3, 1, 'AIガバナンスフレームワーク構築の最初のステップは何ですか？', '最新のAI技術を導入する', '組織の価値観、ミッション、リスク許容度に基づく AI戦略を定め、経営層の承認を得る', 'すぐにAIプロジェクトを開始', 'ガバナンスは後から構築できる', 1, 'AIガバナンスの成功には、組織全体が共有する明確な方針・戦略が必須です。'),
(4, 3, 2, '多段階のAI監査プロセスにおいて最も重要なステップは何ですか？', 'AIの販売後のみ監査', 'デザイン段階、開発段階、運用段階での継続的な監査を実施し、新の脅威・倫理的課題を検出', '監査は1回だけ', '外部監査は不要', 1, 'ライフサイクル全体での継続的な監査により、新しい脅威やバイアスの漂流を早期に検出・対応できます。'),
(4, 3, 3, 'AIモデルの「ドリフト（Drift）」が何を指し、その対策は何ですか？', 'モデルの移動', '時間経過でモデルの予測精度が低下すること。再学習や新データへの継続的適応により対策', 'ドリフトは無害', '対策は不要', 1, 'AIモデルドリフトは運用環境でのデータ変化により発生し、定期的なモニタリングと再学習が必要です。'),
(4, 3, 4, 'サイバーセキュリティ経営（Cyber Risk Governance）とAIの関係は何ですか？', 'AIはセキュリティ経営と無関係', 'AIは脅威検知・インシデント対応などセキュリティ強化の重要な手段となる一方、AIシステム自体のセキュリティリスク管理も経営課題', '経営層はセキュリティを考慮しなくていい', 'AIはセキュリティを無視できる', 1, 'AI活用はサイバーセキュリティ経営の戦略的課題であり、リスク と機会の両面を経営レベルで判断する必要があります。'),
(4, 3, 5, 'AI導入企業における「データトラストスコア」の目的は何ですか？', 'データベースのパフォーマンス測定', 'データの品質・セキュリティ・倫理的利用の実績に基づき、組織のデータ運用への信頼度を数値化・可視化', 'スコアは必要ない', 'データの価値を測定する', 1, 'データトラストスコアは、ステークホルダーに対する説明責任とAI信頼の基盤を提供します。'),
(4, 3, 6, 'AI倫理の「多様性と包括性（Diversity & Inclusion）」の重要性は何ですか？', '多様性はAIと無関係', 'AIの設計・開発・運用に多様な背景の人物を参画させ、バイアスや見落としを減らすこと', '同一の視点で十分', '多様性はコスト', 1, '多様なチーム構成により、異なる視点からの懸念が検出され、より公正で包括的なAIシステムが実現されます。'),
(4, 3, 7, 'AIのスタートアップが大企業のGDPR・規制に遵守するための戦略は何ですか？', '規制を無視する', '初期段階からプライバシー・セキュリティ・監査をプロダクトに組み込み、段階的にコンプライアンスを構築', '大企業になるまで対応延期', 'スタートアップは免除される', 1, 'スタートアップでも初期段階からコンプライアンスを組み込むことで、スケール時の問題を予防できます。'),
(4, 3, 8, 'AIの「第三者評価（Third-party Audit）」の価値は何ですか？', '外部評価は不要', '独立した第三者がAIの倫理・セキュリティ・法令遵守を客観的に評価し、ステークホルダーの信頼を構築', '企業の自己評価で十分', '評価にコストはかかるから不要', 1, '第三者評価により、組織内の利益相反を排除し、透明で信頼性の高いAI運用の実績を証明できます。'),
(4, 3, 9, 'AI導入企業における継続的改善（Continuous Improvement）メカニズムの重要性は何ですか？', '改善は不要', 'フィードバック循環、パフォーマンス監視、新知見の適用により、AI運用を継続的に向上させること', '導入後は静的に運用', '改善はAIに関係ない', 1, 'AI運用は動的であり、継続的な改善メカニズムにより、新規リスク対応と効果最大化を実現します。'),
(4, 3, 10, 'AI規制の「サンドボックス（Regulatory Sandbox）」の役割は何ですか？', 'AIを隔離する場所', '規制の例外適用のもと、イノベーティブなAIプロジェクトを試験的に実施・評価し、適切な規制の枠組みを構築', 'サンドボックスは不要', '規制を回避する仕組み', 1, 'Regulatory Sandboxは、革新的AI開発と規制適合の両立を目指す重要な仕組みです。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(5, 1, 1, 'ゼロトラストセキュリティ（Zero Trust）の基本原則は何ですか？', 'すべてを信頼する', '「信頼を前提としない」 - すべてのリクエストを認証・検証し、常にセキュリティを確認する', 'インターネットを信頼する', '認証は不要', 1, 'ゼロトラスト原則では、内部・外部を区別せず、すべてのアクセスを厳格に検証することを要求します。'),
(5, 1, 2, 'ゼロトラストアーキテクチャにおいて AI を活用する利点は何ですか？', 'AIは不要', 'AIが異常なアクセスパターンをリアルタイムで検出し、より効果的な脅威検知が可能', 'ゼロトラストは古い手法', 'AIで脅威は完全に防げる', 1, 'ゼロトラストにおけるAI活用は、既知・未知の脅威を自動検出する重要な役割を果たします。'),
(5, 1, 3, 'SOC（Security Operations Center）とは何ですか？', 'インターネット検索エンジン', 'セキュリティイベントを監視・検出・対応する組織的な機能', 'セキュリティは不要', 'ソーシャルメディアのプラットフォーム', 1, 'SOCは24/7で脅威を監視し、インシデント対応を実施する組織のセキュリティハブです。'),
(5, 1, 4, 'SIEM（Security Information and Event Management）の役割は何ですか？', 'ソーシャルメディアの管理', 'ネットワーク・アプリケーション・セキュリティデバイスからのログを集約・分析し、脅威を検知', 'セキュリティ情報の収集は不要', 'イベント分析は手動でいい', 1, 'SIEMは、大規模なセキュリティ環境で発生した数百万のイベントから脅威シグナルを検出します。'),
(5, 1, 5, 'SIEMへのAI導入による改善点は何ですか？', 'AIは必要ない', 'ルールベース検知の限界を超えて、ノイズ削減と新型攻撃の検出が可能', 'SIEMの速度が落ちる', 'アラート数が増える', 1, 'AI-エンハンスドSIEMは、機械学習で異常パターンを学習し、従来の方法では見つからない脅威を検出します。'),
(5, 1, 6, 'EDR（Endpoint Detection and Response）の機能は何ですか？', 'メールフィルタリング', 'エンドポイント（PCやサーバー）のプロセス・ネットワーク活動を監視・分析し、脅威を検知・対応', 'エンドポイント保護は不要', 'ウイルス検査のみ', 1, 'EDRは従来のアンチウイルスよりも高度な脅威検知と迅速な対応を実現します。'),
(5, 1, 7, 'AIを用いたEDRの検知精度が向上する理由は何ですか？', 'AIは不正確である', 'AIが未知のマルウェア動作パターンを学習し、シグネチャベース検知では検出不可能な脅威を特定', '精度は変わらない', '検知は簡単である', 1, 'AI-驅動EDRは未知の脅威やゼロデイマルウェアの行動パターンを動的に検出できます。'),
(5, 1, 8, 'インシデント検知後の「対応（Response）」に AI を使う意義は何ですか？', 'AIは対応できない', 'AIが自動化・優先付けを行い、SOC チームが効率的に対応する', '対応は手動のみ', 'AIの使用は禁止', 1, 'AIによるインシデント対応の自動化により、重大脅威への対応時間が大幅に短縮できます。'),
(5, 1, 9, 'SOAR（Security Orchestration, Automation and Response）の目的は何ですか？', 'ロボット工学', 'セキュリティツール間の連携を自動化し、インシデント対応の時間短縮と効率化', 'セキュリティツールは不要', 'アラートは全て手動対応', 1, 'SOARはセキュリティプレイブックを自動実行し、SOC チームの業務負荷を大幅に軽減します。'),
(5, 1, 10, 'AIセキュリティ運用における人間の役割は何ですか？', 'AIが全て判断するため人間は不要', 'AIの判断を検証・承認し、複雑な脅威分析・対応戦略を策定', 'AIなしで全て手動実行', 'セキュリティは無視できる', 1, 'AI-人間協働モデルでは、AIが自動化可能な低次タスクを担当し、人間は高度な判断に集中します。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(5, 2, 1, 'インシデント対応（Incident Response）における AI 活用の段階は何ですか？', 'AIは使わない', '検知→分類→調査→対応→復旧の全段階でAIを活用し、サイクルタイムを短縮', 'AIは対応のみ', 'AIは準備段階のみ', 1, 'AI-駆動インシデント対応は全段階で効率化を実現し、MTTR（平均修復時間）を大幅に削減できます。'),
(5, 2, 2, '脆弱性管理（Vulnerability Management）における AI の活用例は何ですか？', 'AIは使えない', 'AIが発見された脆弱性の重要度を判定し、修復優先順位を自動決定', '脆弱性スキャンは不要', 'すべての脆弱性は重要', 1, 'AI-駆動脆弱性管理は、膨大な脆弱性の中から「実際のリスク」に焦点を当てた優先順位付けを実現します。'),
(5, 2, 3, 'ペネトレーションテスト（Penetration Test）で AI を使う利点は何ですか？', 'AI は使わない', 'AIが自動的に攻撃経路を検索・記録し、手作業的な負担を減らしながら未知の脆弱性を発見', 'ペンテストは手動のみ', 'AIは攻撃を支援できない', 1, 'AI-支援ペンテストは、テスター人員不足を補いながら、自動では見つけられない脆弱性を発見できます。'),
(5, 2, 4, '脅威インテリジェンス（Threat Intelligence）における AI の役割は何ですか？', 'AIは不要', 'AIが膨大な脅威データを分析し、組織に関連する脅威を自動抽出・優先付け', 'インテリジェンス収集は手動のみ', 'すべての脅威は等しく重要', 1, 'AI-駆動脅威インテリジェンスは、組織固有のリスク像を自動構築し、限定的なセキュリティリソースの最適配分を実現します。'),
(5, 2, 5, 'ユーザー行動分析（UBA: User Behavior Analytics）の機能は何ですか？', 'ユーザーを監視することのみ', 'ユーザーの通常パターンを学習し、異常な行動（アカウント乗っ取り・内部脅威など）をリアルタイム検出', 'ユーザー分析は不要', 'すべてのユーザーは信頼できる', 1, 'UBAは機械学習により、ユーザーの正常行動ベースラインを自動構築し、内部脅威を効果的に検出します。'),
(5, 2, 6, 'フィッシング対策にAI を導入する実装方法は何ですか？', 'フィッシング対策は不要', 'メールフィルタ、送信者検証、リンク分析、ユーザーの不安なクリックの検出をAIで自動化', 'フィッシングは手動検査のみ', 'ユーザー教育は不要', 1, 'AIベースのフィッシング対策は、自動フィッシング（AI活用）による増加に対抗する防御手段です。'),
(5, 2, 7, 'APT（Advanced Persistent Threat）対策における AI の活用は何ですか？', 'APT対策にAIは不要', 'AIが複雑な攻撃チェーン・横展開パターンを検出し、APTキャンペーンの早期発見を実現', 'APTは防御不可能', 'APT検知は手動のみで可能', 1, 'AI-驅動APT検知は、多段階の後付け的な攻撃パターンを自動認識し、キャンペーン全体を可視化します。'),
(5, 2, 8, 'ランサムウェア対策における AI の役割は何ですか？', 'AIは使えない', 'AIが暗号化・削除活動などランサムウェアの兆候を検出し、感染初期に駆除', 'ランサムウェア検知は手動のみ', 'ランサムウェアは防御不可能', 1, 'AI-基盤ランサムウェア検知は、ファイアウォールでは通過するランサムウェアの活動を検出します。'),
(5, 2, 9, 'API セキュリティにおける AI 活用は何ですか？', 'APIセキュリティにAIは不要', 'AIが異常なAPIアクセスパターン・不正なペイロード・エラーレート急増を検出', 'APIセキュリティは不要', 'すべてのAPIアクセスは許可', 1, 'API-based攻撃（モデル窃取、DDoS）に対して、AI-駆動検知が効果的な防御を提供します。'),
(5, 2, 10, 'コンテナセキュリティ（Container Security）における AI 活用の例は何ですか？', '使い捨てコンテナだから対策は不要', 'AIが悪意のあるイメージ、設定ミス、ランタイム異常を検出・防止', 'コンテナセキュリティは手動のみ', 'コンテナは本質的にセキュア', 1, 'AI-駆動コンテナセキュリティは、DevOps パイプライン統合で脆弱性を早期に検出・修復します。');
INSERT INTO questions (stage_id, class_id, question_number, question_text, choice_a, choice_b, choice_c, choice_d, correct_index, explanation) VALUES
(5, 3, 1, 'AIセキュリティ組織の構造設計における最適な形態は何ですか？', 'セキュリティはIT部門に任せる', 'セキュリティ、AI/ML、ビジネス、法務が連携し、AI脅威への戦略的対応を実現', 'AI部門とセキュリティ部門は分離', '統制は不要', 1, 'AIセキュリティ組織の有効性は、多職種協働と経営層の支援に依存します。'),
(5, 3, 2, 'Red Team / Blue Team 演習における AI の活用は何ですか？', 'AIは使わない', 'Red Team がAIを用いて攻撃シミュレーション、Blue Team がAI防御を検証し、組織のレジリエンス評価', 'Red/Blue Team は古い手法', 'AI攻撃シミュレーションは不可能', 1, 'AI-enhanced Red/Blue Team演習は、実際のAI駆動脅威に対する組織のレジリエンスを検証します。'),
(5, 3, 3, '最先端AIセキュリティ技術として最も期待されているものは何ですか？', '既知の脅威対策の繰り返し', '説明可能AI（Explainable AI）を用いた脅威検知・対応の可視化と信頼構築', '最先端技術は不要', 'セキュリティは静的である', 1, 'XAI-駆動セキュリティは、AI判定の透明性を確保し、SOC チームの効率的な対応を実現します。'),
(5, 3, 4, 'AIリスク評価フレームワーク（AI Risk Assessment Framework）の要素は何ですか？', 'リスク評価は不要', 'データ、モデル、インフラ、運用、倫理の各層でAIシステムのリスクを多面的に評価', '評価は開発後のみ', 'リスク無視は許容', 1, '多層的なAIリスク評価は、深刻な問題の早期発見と体系的な対策実施を可能にします。'),
(5, 3, 5, 'Zero Trust+AI の統合セキュリティモデルの構成要素は何ですか？', 'ZT とAIは統合不可', 'AI-駆動な認証・監視・対応により、全アクセスの継続的検証と脅威の自動対応を実現', 'Zero Trust のみで十分', 'AIは補助的な役割', 1, 'Zero Trust+AI統合は、最新の脅威ランドスケープに対応する次世代セキュリティパラダイムです。'),
(5, 3, 6, 'AI供給チェーンのセキュリティ監査に含むべき要素は何ですか？', '監査は不要', 'データソース、モデル開発環境、デプロイメント、操作ログ、サプライヤー評価の包括的監視', '監査は開発者の責務のみ', '外部チェックは不要', 1, '供給チェーン監査により、すべての参加者がセキュリティ基準を満たしていることを確保できます。'),
(5, 3, 7, 'AI環境におけるインシデント対応の「シミュレーション（Tabletop Exercise）」の目的は何ですか？', 'シミュレーションは無駄', 'AI起点のセキュリティインシデントシナリオを事前に演習し、チームの準備状態と対応手順を検証', '実際の攻撃の方が良い学習', 'シミュレーションなしで対応できる', 1, 'AI-focused tabletop exercisesは、本番環境でのAIセキュリティインシデント対応能力を事前に構築します。'),
(5, 3, 8, 'Adversarial Robustness Testing（敵対的ロバストネステスト）の実施目的は何ですか？', 'テストは不要', 'AIシステムを意図的に攻撃し、未知の脆弱性・バイアス・振る舞い異常を発見', 'テストは単なる精度確認', 'セキュリティテストはスキップ可能', 1, '敵対的ロバストネステストは、本番環境での予期しない失敗や攻撃耐性を事前に評価します。'),
(5, 3, 9, 'AI セキュリティ メトリクス（Metrics）の設計における注意点は何ですか？', 'メトリクスは不要', 'セキュリティと AI性能の均衡を示す指標を設計し、経営・開発チーム間での意思決定支援', 'メトリクスは直感的判断のみ', 'すべての指標が重要', 1, '適切に設計されたAIセキュリティメトリクスは、組織全体の優先度調整と効果測定を可能にします。'),
(5, 3, 10, 'AI セキュリティの継続的改善（Continuous Improvement）ループの構成は何ですか？', '改善は不要', '脅威検知→分析→対応→学習→戦略更新→テスト→デプロイのサイクル', '改善は年1回のみ', 'セキュリティは静的な目標', 1, '継続的改善ループにより、組織はAIセキュリティの最新ベストプラクティスに追従し、脅威に適応します。');
